import { z } from "zod";
import { LEVELS } from "@/domain/model";

/**
 * Pronunciation audio (DECISIONS "Pronunciation audio"): one small MP3 per
 * word in public/audio/v1, generated by `npm run audio:build`. A human
 * recording from Wikimedia Commons when one with an allowed licence exists,
 * otherwise the offline neural voice. Read over the network, so validated.
 */

const hashed = (re: RegExp) => z.string().regex(re);
/** "w-apple.3fa2c1d9e0.mp3": the word id, a content hash, MP3. */
const audioFile = hashed(/^w-[a-z0-9-]+\.[0-9a-f]{10}\.mp3$/);

export const audioManifestSchema = z
  .object({
    version: z.literal(1),
    /** The accent of every file (only American audio exists so far). */
    accent: z.enum(["us", "uk"]),
    voice: z.object({ name: z.string().min(1), license: z.string().min(1), url: z.string().url() }).strict(),
    credits: z.object({ path: hashed(/^audio-credits\.[0-9a-f]{10}\.tsv$/), bytes: z.number().int().positive() }).strict(),
    levels: z.partialRecord(
      z.enum(LEVELS),
      z
        .object({
          index: hashed(/^index-(A1|A2|B1|B2|C1)\.[0-9a-f]{10}\.json$/),
          bytes: z.number().int().positive(),
          files: z.number().int().positive(),
          audioBytes: z.number().int().positive(),
        })
        .strict(),
    ),
  })
  .strict();
export type AudioManifest = z.infer<typeof audioManifestSchema>;

/** [author, licence short name, licence URL ("" for public domain)] */
const creditSchema = z.tuple([z.string().min(1).max(80), z.string().min(1).max(40), z.string()]);

/** id -> [file, credit index (-1: the generated voice), Commons file name for a human recording] */
const entrySchema = z.union([z.tuple([audioFile, z.literal(-1)]), z.tuple([audioFile, z.number().int().nonnegative(), z.string().min(1).max(200)])]);

export const audioIndexSchema = z
  .object({
    level: z.enum(LEVELS),
    credits: z.array(creditSchema),
    files: z.record(z.string().regex(/^w-[a-z0-9-]+$/), entrySchema),
  })
  .strict()
  .refine((ix) => Object.values(ix.files).every((e) => e[1] < ix.credits.length), "credit index out of range");
export type AudioIndex = z.infer<typeof audioIndexSchema>;

/** Credit for a human recording, shown after the answer and on /credits. */
export interface RecordingCredit {
  readonly author: string;
  readonly license: string;
  readonly licenseUrl: string;
  /** The file page on Wikimedia Commons. */
  readonly page: string;
}

export const commonsPage = (title: string): string => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(title.replaceAll(" ", "_"))}`;
